// Recibe el texto que viene de tu AI Agent (Groq / Llama)
const rawOutput = $input.item.json.output; 

let parsedJson = {};

try {
  // Convierte el string devuelto por la IA en un objeto JSON real
  parsedJson = JSON.parse(rawOutput);
} catch (error) {
  // Por si la IA envió texto adicional o cometió un error de sintaxis
  console.error("Error al parsear el JSON:", error);

  // Limpieza rápida por si la IA devolvió bloques tipo ```json ... ```
  const cleanedText = rawOutput.replace(/```json|```/g, '').trim();
  parsedJson = JSON.parse(cleanedText);
}

// Devuelve las variables separadas para usarlas fácilmente en un nodo Switch/If
return {
  json: {
    value: parsedJson.value,
    borrar: parsedJson.borrar,
    fuente: parsedJson.consulta?.fuente || "ambas",
    es_consulta: parsedJson.consulta?.booleano || false,
    es_resumen: parsedJson.resumen || false
  }
};

